const registration = await navigator.serviceWorker.ready;
const existing = await registration.pushManager.getSubscription();
if (existing) {
  const raw = existing.getKey('applicationServerKey');
  const norm = (s: string) =>
    s.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  const serverKey = norm(publicKey);
  const existingKey = raw
    ? norm(btoa(String.fromCharCode(...new Uint8Array(raw))))
    : null;
  if (existingKey && existingKey === serverKey) return; // already current
  await existing.unsubscribe();
}
